#include <algorithm>

using namespace std;

int main()
{
    int n, m, a, b;
    cin >> n >> m >> a >> b;

    if (a > b)
        swap(a, b);

    if ((a % m == 1 && b == n) ||
        ((a - 1) / m == (b - 1) / m) ||
        (((a - 1) % m == 0 && b % m == 0) && a % m != 0))
    {
        cout << 1;
        return 0;
    }

    if ((a % m == 1 && b % m != 0) ||
        (a % m != 1 && b % m == 0) ||
        (a % m - 1 == b % m) ||
        (b == n) ||
        ((a - 1) / m + 1 == (b - 1) / m) ||
        ((a - 1) % m == b % m))
    {
        cout << 2;
        return 0;
    }

    cout << 3;
    return 0;
}

